import { createContext } from "svelte";
import type {
	SwipeActionsContextValue,
	SwipeId,
	SwipeItemContextValue,
	SwipeRootContextValue
} from "./swipe-actions-types";

const [getRootContext, setSwipeRootContext] =
	createContext<SwipeRootContextValue>();
const [getItemContext, setSwipeItemContext] =
	createContext<SwipeItemContextValue>();
const [getActionsContext, setSwipeActionsContext] =
	createContext<SwipeActionsContextValue>();
const [getActionIdContext, setSwipeActionIdContext] = createContext<SwipeId>();

export function useSwipeRoot(): SwipeRootContextValue | null {
	try {
		return getRootContext();
	} catch {
		return null;
	}
}

export function useSwipeItem(): SwipeItemContextValue {
	try {
		return getItemContext();
	} catch {
		throw new Error("Swipe parts must be used within SwipeItem");
	}
}

export function useSwipeActions(): SwipeActionsContextValue {
	try {
		return getActionsContext();
	} catch {
		throw new Error("SwipeAction must be used within SwipeActions");
	}
}

export function useSwipeActionId(): SwipeId {
	try {
		return getActionIdContext();
	} catch {
		throw new Error("SwipeActionContent must be used within SwipeAction");
	}
}

export {
	setSwipeActionIdContext,
	setSwipeActionsContext,
	setSwipeItemContext,
	setSwipeRootContext
};

import { animate, useMotionValue } from "motion-sv";
import { SvelteMap } from "svelte/reactivity";
import type {
	DragHandler,
	SwipeId,
	SwipeItemContextValue,
	SwipeRootContextValue,
	SwipeSide,
	SwipeState
} from "./swipe-actions-types";
import {
	DRAG_SLOP,
	GESTURE_SPRING,
	getReleaseState,
	getSnapTarget,
	SNAP_SPRING,
	TAKEOVER_TWEEN
} from "./swipe-actions-utils";

export class SwipeRootState implements SwipeRootContextValue {
	#registry = new SvelteMap<SwipeId, () => void>();

	register = (id: SwipeId, close: () => void): VoidFunction => {
		this.#registry.set(id, close);
		return () => this.#registry.delete(id);
	};

	notifyOpen = (id: SwipeId) => {
		for (const [key, close] of this.#registry) {
			if (key !== id) close();
		}
	};
}

type SwipeItemOptions = {
	id: SwipeId;
	group: SwipeRootContextValue | null;
	threshold: () => number;
	velocityFactor: () => number;
	fullSwipeThreshold: () => number;
	disabled: () => boolean;
	shouldReduceMotion: () => boolean;
	onOpenChange: () => ((state: SwipeState) => void) | undefined;
};

export class SwipeItemState implements SwipeItemContextValue {
	state = $state<SwipeState>("closed");
	dragging = $state(false);
	armed = $state<SwipeSide | null>(null);
	leftWidth = $state(0);
	rightWidth = $state(0);
	itemWidth = $state(0);
	fullSwipeSides = $state<Record<SwipeSide, boolean>>({
		left: false,
		right: false
	});

	readonly x = useMotionValue(0);
	readonly collapse = useMotionValue(1);

	#dragged = false;
	#fullSwipeActions: Record<SwipeSide, SvelteMap<SwipeId, () => void>> = {
		left: new SvelteMap(),
		right: new SvelteMap()
	};
	#options: SwipeItemOptions;

	constructor(options: SwipeItemOptions) {
		this.#options = options;
	}

	get disabled() {
		return this.#options.disabled();
	}

	setItemWidth = (width: number) => {
		if (this.itemWidth === width) return;
		this.itemWidth = width;
	};

	setStripWidth = (side: SwipeSide, width: number) => {
		const current = side === "left" ? this.leftWidth : this.rightWidth;
		if (current === width) return;

		if (side === "left") this.leftWidth = width;
		else this.rightWidth = width;

		if (this.state === side) {
			this.x.set(side === "left" ? width : -width);
		}
	};

	registerFullSwipe = (
		side: SwipeSide,
		id: SwipeId,
		run: () => void
	): VoidFunction => {
		const actions = this.#fullSwipeActions[side];
		actions.set(id, run);
		if (!this.fullSwipeSides[side]) this.fullSwipeSides[side] = true;

		return () => {
			actions.delete(id);
			if (actions.size === 0) this.fullSwipeSides[side] = false;
		};
	};

	#getFullSwipeAction(side: SwipeSide) {
		const actions = this.#fullSwipeActions[side];
		return Array.from(actions.values()).at(-1);
	}

	#setArmed(side: SwipeSide | null) {
		if (this.armed === side) return;
		this.armed = side;
		animate(
			this.collapse,
			side ? 0 : 1,
			this.#options.shouldReduceMotion()
				? { duration: 0 }
				: TAKEOVER_TWEEN
		);
	}

	settle = (next: SwipeState, releaseVelocity?: number) => {
		const widths = { left: this.leftWidth, right: this.rightWidth };
		const target = getSnapTarget(next, widths);
		const transition = this.#options.shouldReduceMotion()
			? { duration: 0 }
			: releaseVelocity === undefined
				? SNAP_SPRING
				: { ...GESTURE_SPRING, velocity: releaseVelocity };

		const isSettled =
			this.state === next && Math.abs(this.x.get() - target) < 0.5;
		if (isSettled) return;

		animate(this.x, target, transition);
		if (next !== "closed")
			this.#options.group?.notifyOpen(this.#options.id);
		if (this.state === next) return;

		this.state = next;
		this.#options.onOpenChange()?.(next);
	};

	close = () => this.settle("closed");

	onDragStart: DragHandler = () => {
		this.#dragged = false;
		this.dragging = true;
		this.#options.group?.notifyOpen(this.#options.id);
	};

	onDrag: DragHandler = (_, info) => {
		if (Math.abs(info.offset.x) > DRAG_SLOP) this.#dragged = true;

		const reach = this.#options.fullSwipeThreshold() * this.itemWidth;
		const travel = this.x.get();
		if (reach <= 0) {
			this.#setArmed(null);
			return;
		}

		if (travel <= -reach && this.fullSwipeSides.right) {
			this.#setArmed("right");
		} else if (travel >= reach && this.fullSwipeSides.left) {
			this.#setArmed("left");
		} else {
			this.#setArmed(null);
		}
	};

	onDragEnd: DragHandler = (_, info) => {
		this.dragging = false;

		if (this.armed) {
			const side = this.armed;
			this.#setArmed(null);
			this.#dragged = false;
			this.#getFullSwipeAction(side)?.();
			this.settle("closed", info.velocity.x);
			return;
		}

		this.settle(
			getReleaseState({
				position: this.x.get(),
				velocity: info.velocity.x,
				velocityFactor: this.#options.velocityFactor(),
				threshold: this.#options.threshold(),
				widths: { left: this.leftWidth, right: this.rightWidth }
			}),
			info.velocity.x
		);
	};

	onClickCapture = (event: MouseEvent) => {
		if (!this.#dragged && this.state === "closed") return;

		event.preventDefault();
		event.stopPropagation();
		if (this.#dragged) {
			this.#dragged = false;
			return;
		}
		this.close();
	};

	onKeyDown = (event: KeyboardEvent) => {
		if (this.disabled) return;
		if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return;

		const [closes, opens] =
			event.key === "ArrowLeft"
				? (["left", "right"] as const)
				: (["right", "left"] as const);

		if (this.state === closes) this.settle("closed");
		else if ((opens === "left" ? this.leftWidth : this.rightWidth) > 0) {
			this.settle(opens);
		} else return;

		event.preventDefault();
	};
}

import type { Snippet } from "svelte";
import type {
	ClassValue,
	HTMLAttributes,
	HTMLButtonAttributes
} from "svelte/elements";
import type {
	MotionHTMLAttributes,
	MotionProps,
	MotionStyleProps,
	MotionValue,
	PanInfo
} from "motion-sv";

export type SwipeSide = "left" | "right";
export type SwipeState = "closed" | SwipeSide;

export type SwipeItemState = {
	state: SwipeState;
	disabled: boolean;
	dragging: boolean;
};

type DivProps = Omit<HTMLAttributes<HTMLDivElement>, "children">;
type ButtonProps = Omit<HTMLButtonAttributes, "children">;
type SpanProps = Omit<HTMLAttributes<HTMLSpanElement>, "children">;
type MotionDivProps = MotionProps<"div"> & MotionHTMLAttributes<"div">;

export type SwipeRootProps = DivProps & {
	children: Snippet;
	ref?: HTMLDivElement | null;
};

export type SwipeItemProps = Omit<DivProps, "onkeydown"> & {
	children: Snippet;
	/** Fraction of the action-strip width the drag must pass to open. @default 0.5 */
	threshold?: number;
	/** Seconds of velocity projected onto the release position. @default 0.2 */
	velocityFactor?: number;
	/** Fraction of the item width the drag must pass to arm a full swipe. @default 0.5 */
	fullSwipeThreshold?: number;
	/** Prevents pointer and keyboard swiping. @default false */
	disabled?: boolean;
	/** Close the item when any page scroll occurs. @default false */
	closeOnScroll?: boolean;
	onOpenChange?: (state: SwipeState) => void;
	onkeydown?: (
		event: KeyboardEvent & { currentTarget: HTMLDivElement }
	) => void;
	ref?: HTMLDivElement | null;
};

export type SwipeActionsProps = DivProps & {
	children: Snippet;
	side: SwipeSide;
	/** Run the outermost action when the drag passes the full-swipe threshold. */
	fullSwipe?: boolean;
	ref?: HTMLDivElement | null;
};

export type SwipeActionProps = Omit<ButtonProps, "onclick" | "type"> & {
	children: Snippet;
	/** Close the item after an unprevented click. @default true */
	closeOnClick?: boolean;
	onclick?: (
		event: MouseEvent & { currentTarget: HTMLButtonElement }
	) => void;
	ref?: HTMLButtonElement | null;
};

export type SwipeActionContentProps = SpanProps & {
	children: Snippet;
	ref?: HTMLSpanElement | null;
};

export type SwipeContentProps = Omit<
	MotionDivProps,
	| "children"
	| "class"
	| "style"
	| "ref"
	| "drag"
	| "dragConstraints"
	| "dragElastic"
	| "dragMomentum"
	| "onDragStart"
	| "onDrag"
	| "onDragEnd"
> & {
	children: Snippet;
	class?: ClassValue;
	style?: MotionStyleProps;
	ref?: HTMLDivElement | null;
};

export type DragHandler = (event: PointerEvent, info: PanInfo) => void;
export type SwipeId = symbol;

export type SwipeRootContextValue = {
	register: (id: SwipeId, close: () => void) => VoidFunction;
	notifyOpen: (id: SwipeId) => void;
};

export type SwipeItemContextValue = {
	readonly state: SwipeState;
	readonly disabled: boolean;
	readonly dragging: boolean;
	readonly x: MotionValue<number>;
	readonly collapse: MotionValue<number>;
	readonly leftWidth: number;
	readonly rightWidth: number;
	readonly itemWidth: number;
	readonly armed: SwipeSide | null;
	readonly fullSwipeSides: Record<SwipeSide, boolean>;
	setItemWidth: (width: number) => void;
	setStripWidth: (side: SwipeSide, width: number) => void;
	registerFullSwipe: (
		side: SwipeSide,
		id: SwipeId,
		run: () => void
	) => VoidFunction;
	close: () => void;
	onDragStart: DragHandler;
	onDrag: DragHandler;
	onDragEnd: DragHandler;
	onClickCapture: (event: MouseEvent) => void;
	onKeyDown: (event: KeyboardEvent) => void;
};

export type SwipeActionsContextValue = {
	readonly side: SwipeSide;
	readonly fullSwipe: boolean;
	measure: (id: SwipeId, width: number) => void;
	forget: (id: SwipeId) => void;
	offsetOf: (id: SwipeId) => number;
	isOutermost: (id: SwipeId) => boolean;
};

import type { SwipeSide, SwipeState } from "./swipe-actions-types";

export const SNAP_SPRING = {
	type: "spring",
	stiffness: 500,
	damping: 45,
	mass: 0.8
} as const;

export const GESTURE_SPRING = { ...SNAP_SPRING, damping: 36 } as const;
export const TAKEOVER_TWEEN = {
	duration: 0.18,
	ease: [0.32, 0.72, 0, 1]
} as const;
export const DRAG_SLOP = 4;

export function getSnapTarget(
	state: SwipeState,
	widths: Record<SwipeSide, number>
): number {
	if (state === "left") return widths.left;
	if (state === "right") return -widths.right;
	return 0;
}

export function getReleaseState({
	position,
	velocity,
	velocityFactor,
	threshold,
	widths
}: {
	position: number;
	velocity: number;
	velocityFactor: number;
	threshold: number;
	widths: Record<SwipeSide, number>;
}): SwipeState {
	const projected = position + velocity * velocityFactor;

	if (widths.right > 0 && projected <= -widths.right * threshold) {
		return "right";
	}
	if (widths.left > 0 && projected >= widths.left * threshold) {
		return "left";
	}
	return "closed";
}

export function sideTravel(side: SwipeSide, position: number): number {
	return Math.max(0, side === "left" ? position : -position);
}

import SwipeAction from "./swipe-action.svelte";
import SwipeActionContent from "./swipe-action-content.svelte";
import SwipeActions from "./swipe-actions.svelte";
import SwipeContent from "./swipe-content.svelte";
import SwipeItem from "./swipe-item.svelte";
import SwipeRoot from "./swipe-root.svelte";

export {
	SwipeAction,
	SwipeActionContent,
	SwipeActions,
	SwipeContent,
	SwipeItem,
	SwipeRoot
};

export type {
	SwipeActionContentProps,
	SwipeActionProps,
	SwipeActionsProps,
	SwipeContentProps,
	SwipeItemProps,
	SwipeItemState,
	SwipeRootProps,
	SwipeSide,
	SwipeState
} from "./swipe-actions-types";

import {
	SwipeActions as Actions,
	SwipeItem as Item,
	SwipeRoot as Root
} from "./primitives";
import Action from "./swipe-action.svelte";
import Content from "./swipe-content.svelte";

export {
	Action,
	Actions,
	Content,
	Item,
	Root,
	Action as SwipeAction,
	Actions as SwipeActions,
	Content as SwipeContent,
	Item as SwipeItem,
	Root as SwipeRoot
};

export type {
	SwipeActionProps,
	SwipeActionsProps,
	SwipeContentProps,
	SwipeItemProps,
	SwipeItemState,
	SwipeRootProps,
	SwipeSide,
	SwipeState
} from "./primitives";
